def translate(language: str, key: str) -> str:
    return TEXT.get(language, TEXT["de"]).get(key, key)

def validate_translations() -> None:
    de, en = set(TEXT["de"]), set(TEXT["en"])
    if de != en:
        raise ValueError(f"Translation keys differ: only DE={de-en}; only EN={en-de}")
